#include <iostream>
#include <cmath>
using namespace std;

const int N = 105;
const double eps = 1e-8;
int n;
double a[N][N + 1];

bool gauss() {
    for (int i = 1; i <= n; i++) {
        int max_row = i;
        for (int j = i + 1; j <= n; j++) {
            if (fabs(a[j][i]) > fabs(a[max_row][i])) {
                max_row = j;
            }
        }

        for (int j = i; j <= n + 1; j++) {
            swap(a[i][j], a[max_row][j]);
        }

        if (fabs(a[i][i]) < eps) {
            return false;
        }

        for (int j = n + 1; j >= i; j--) {
            a[i][j] /= a[i][i];
        }

        for (int j = 1; j <= n; j++) {
            if (i == j || fabs(a[j][i]) < eps) continue;
            double factor = a[j][i];
            for (int k = i; k <= n + 1; k++) {
                a[j][k] -= factor * a[i][k];
            }
        }
    }
    return true;
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n + 1; j++) {
            cin >> a[i][j];
        }
    }

    if (!gauss()) {
        cout << "No unique solution" << endl;
    } else {
        for (int i = 1; i <= n; i++) {
            cout << a[i][n + 1] << " ";
        }
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

const int MOD = 998244353;

long long power(long long a, long long b) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

long long inv(long long x) {
    return power(x, MOD - 2);
}

long long lagrange(vector<long long>& x, vector<long long>& y, long long X) {
    int n = x.size();
    long long ans = 0;

    for (int i = 0; i < n; i++) {
        long long num = 1, den = 1;
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            num = num * (X - x[j] + MOD) % MOD;
            den = den * (x[i] - x[j] + MOD) % MOD;
        }
        ans = (ans + y[i] * num % MOD * inv(den) % MOD) % MOD;
    }

    return ans;
}

int main() {
    int n;
    cin >> n;
    vector<long long> x(n), y(n);

    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i];
    }

    long long X;
    cin >> X;

    cout << lagrange(x, y, X) << endl;

    return 0;
}
